function points(history,metric='index'){return(history||[]).map(x=>({date:metric==='intraday'?x.timestamp:x.date,value:metric==='intraday'?x.price:metric==='cap'?x.value:x.close??x.value,provider:x.provider,timestamp_quality:x.timestamp_quality})).filter(x=>finite(x.value));}
function chart(history,{height=205,compact=false,color='#4c85d5',metric='index',range=state.range}={}) {
  let values=points(history,metric);if(range)values=values.slice(-range);
  if(values.length<2||(metric==='intraday'&&new Set(values.map(v=>v.date)).size<2))return compact?null:h('div',{class:'empty-chart'},h('span',{},metric==='intraday'?'分时有效报价时点不足两个 · 等待下一次采样':metric==='cap'?'历史市值样本不足 · 持续记录中':'等待真实行情历史'));
  const w=620, hh=height, left=compact?0:8,right=compact?0:56,top=compact?3:14,bottom=compact?3:30;
  let lo=Math.min(...values.map(v=>Number(v.value))),hi=Math.max(...values.map(v=>Number(v.value)));let pad=(hi-lo)*.18||Math.max(Math.abs(hi)*.005,1);lo-=pad;hi+=pad;
  const firstTime=new Date(values[0].date).getTime(),lastTime=new Date(values.at(-1).date).getTime();const X=i=>left+(metric==='intraday'&&lastTime>firstTime?(new Date(values[i].date).getTime()-firstTime)/(lastTime-firstTime):i/(values.length-1))*(w-left-right),Y=v=>top+(hi-Number(v))/(hi-lo)*(hh-top-bottom);
  const el=s('svg',{viewBox:`0 0 ${w} ${hh}`,class:compact?'spark':'chart',role:'img','aria-label':`${metric==='intraday'?'分时快照':metric==='cap'?'市值':'指数'}趋势，${values[0].date}至${values.at(-1).date}`});
  if(!compact){for(let i=0;i<5;i++){let y=top+i*(hh-top-bottom)/4;el.append(s('line',{x1:left,y1:y,x2:w-right,y2:y,stroke:'#e9eef4','stroke-dasharray':'3 5'}));const text=s('text',{x:w-right+10,y:y+3});text.textContent=metric==='cap'?amount(hi-(hi-lo)*i/4):num(hi-(hi-lo)*i/4,0);el.append(text);}for(let i=0;i<4;i++){let j=Math.round(i*(values.length-1)/3);const t=s('text',{x:X(j),y:hh-7,'text-anchor':i===0?'start':i===3?'end':'middle'});t.textContent=metric==='intraday'?dateText(values[j].date,true):String(values[j].date).slice(5);el.append(t);}}
  const line=values.map((v,i)=>`${i?'L':'M'}${X(i).toFixed(2)} ${Y(v.value).toFixed(2)}`).join(' ');
  if(!compact&&metric!=='intraday')el.append(s('path',{d:`${line} L${X(values.length-1)} ${hh-bottom} L${left} ${hh-bottom} Z`,fill:color,opacity:.065}));
  const providerColor=p=>p==='sina'?'#b68d4f':p==='tencent'?'#4c85d5':color;
  if(metric==='intraday'){for(const provider of new Set(values.map(v=>v.provider))){const grouped=values.map((v,i)=>({v,i})).filter(x=>x.v.provider===provider);const path=grouped.map((x,j)=>`${j?'L':'M'}${X(x.i).toFixed(2)} ${Y(x.v.value).toFixed(2)}`).join(' ');el.append(s('path',{d:path,stroke:providerColor(provider),'stroke-width':1.7,fill:'none','stroke-dasharray':'3 3'}));}}else el.append(s('path',{d:line,stroke:color,'stroke-width':compact?3:2,fill:'none','stroke-linecap':'round','stroke-linejoin':'round'}));
  if(metric==='intraday'){values.forEach((v,i)=>{const dot=s('circle',{cx:X(i),cy:Y(v.value),r:4,fill:providerColor(v.provider),'fill-opacity':.65,tabindex:0});const label=s('title');label.textContent=`${v.timestamp_quality==='retrieved_only'?'采集时间（未确认源时点）':'来源时间'} ${dateText(v.date,false)} · ${num(v.value,3)} · ${v.provider||'来源未提供'} · ${v.timestamp_quality==='retrieved_only'?'仅采集时点':'来源报价时点'}`;dot.append(label);el.append(dot);});}if(!compact){let last=values.at(-1);el.append(s('circle',{cx:X(values.length-1),cy:Y(last.value),r:3.5,fill:color,stroke:'#fff','stroke-width':2}));const title=s('title');title.textContent=`${last.date}: ${num(last.value)}`;el.append(title);}return el;
}
