function fundPremium(f) {
  if(!finite(f.price)||!finite(f.nav)||Number(f.nav)<=0||!f.price_date||chinaDay(f.price_date)!==chinaDay(f.nav_date))return null;
  return (Number(f.price)/Number(f.nav)-1)*100;
}
