function validateSnapshot(result){if(!result||typeof result!=='object'||Array.isArray(result)||result.schema_version!==1||!Array.isArray(result.sectors)||!Array.isArray(result.market))throw new Error('数据格式不符合约定');for(const key of ['news','predictions','ledger','sources','notices','data_checks'])if(key in result&&!Array.isArray(result[key]))throw new Error(`数据字段 ${key} 格式不符合约定`);for(const key of ['market_session','models','daily_review','intraday','equity_forecast'])if(key in result&&(result[key]===null||typeof result[key]!=='object'||Array.isArray(result[key])))throw new Error(`数据字段 ${key} 格式不符合约定`);if(result.equity_forecast&&'stocks' in result.equity_forecast&&!Array.isArray(result.equity_forecast.stocks))throw new Error('数据字段 equity_forecast.stocks 格式不符合约定');return result;}
function requestSnapshot(fetcher=fetch,cacheBust=Date.now()){const options={cache:'no-store'};const parse=response=>{if(!response.ok)throw new Error(`HTTP ${response.status}`);return response.json();};return fetcher(`./data/view.json?t=${cacheBust}`,options).then(response=>response.status===404?fetcher(`./data/dashboard.json?t=${cacheBust}`,options).then(parse):parse(response)).then(validateSnapshot);}
async function refresh(){state.loading=true;render();try{const result=await requestSnapshot();state.data={...baseData(),...result};state.error=null;demoCache=null;}catch(err){state.error=`研究快照暂不可用（${String(err.message).slice(0,100)}）。可以查看明确标记的演示模式，或在数据设置中检查来源。`;}finally{state.loading=false;render();}}
